    largest = max(lst)

    smaller_nums = [num for num in lst if num < smallest]
    larger_nums = [num for num in lst if num > smallest]

    smaller_nums.sort()
    larger_nums.sort(reverse=True)

    result = []
    for i in range(len(lst)):
        if i % 2 == 0:
            result.append(smaller_nums.pop(0))
        else:
            result.append(larger_nums.pop(0))

    return result

